package it.studio44z.zing.ui

import java.util.Locale

internal fun uiCopy(italian: String, langCode: String): String {
    val language = langCode.lowercase(Locale.ROOT).substringBefore('-').substringBefore('_')
    val dictionary = when (language) {
        "en" -> en
        "es" -> es
        "fr" -> fr
        "de" -> de
        "pt" -> pt
        else -> return italian
    }
    return dictionary[italian]
        ?: extraFeatureTranslations[language]?.get(italian)
        ?: supplementalFeatureTranslations[language]?.get(italian)
        ?: nutritionTextTranslations[language]?.get(italian)
        ?: finalFeatureTranslations[language]?.get(italian)
        ?: releaseFeatureTranslations[language]?.get(italian)
        ?: wikibooksFeatureTranslations[language]?.get(italian)
        ?: recipePolishTranslations[language]?.get(italian)
        ?: adFeatureTranslations[language]?.get(italian)
        ?: nextReleaseTranslations[language]?.get(italian)
        ?: billingStatusTranslations[language]?.get(italian)
        ?: italian
}


