internal fun notificationCopy(italian: String, langCode: String): String {
    val language = langCode.lowercase(Locale.ROOT).substringBefore('-').substringBefore('_')
    val translated = when (language) {
        "en" -> notificationEn[italian]
        "es" -> notificationEs[italian]
        "fr" -> notificationFr[italian]
        "de" -> notificationDe[italian]
        "pt" -> notificationPt[italian]
        else -> null
    }
    return translated ?: uiCopy(italian, langCode)
}

